#include "audiocodecdecoder.hpp"
#include <algorithm>
#include <cstring>
void AudioCodecDecoder::append(const std::string& id,const std::vector<std::uint8_t>& bytes,std::uint64_t generation){
    auto& stream=streams_[id];if(!stream||stream->generation!=generation){stream=std::make_unique<Stream>();stream->generation=generation;stream->timer=std::make_unique<QTimer>();stream->timer->setSingleShot(true);stream->timer->setInterval(150);connect(stream->timer.get(),&QTimer::timeout,this,[this,id]{decode(id);});}
    if(stream->encoded.size()+qsizetype(bytes.size())>16*1024*1024){if(notice)notice("VS1053: encoded stream exceeds the 16 MiB simulation buffer.");return;}
    stream->encoded.append(reinterpret_cast<const char*>(bytes.data()),qsizetype(bytes.size()));if(!stream->timer->isActive())stream->timer->start();
}
void AudioCodecDecoder::decode(const std::string& id){
    auto found=streams_.find(id);if(found==streams_.end())return;auto& stream=*found->second;stream.pcm.clear();stream.decoder.reset();stream.buffer=std::make_unique<QBuffer>();stream.buffer->setData(stream.encoded);stream.buffer->open(QIODevice::ReadOnly);stream.decoder=std::make_unique<QAudioDecoder>();
    QAudioFormat target;target.setSampleRate(48000);target.setChannelCount(2);target.setSampleFormat(QAudioFormat::Int16);stream.decoder->setAudioFormat(target);stream.decoder->setSourceDevice(stream.buffer.get());const auto generation=stream.generation;const auto* decoder=stream.decoder.get();
    connect(stream.decoder.get(),&QAudioDecoder::bufferReady,this,[this,id,generation,decoder]{auto found=streams_.find(id);if(found==streams_.end()||found->second->generation!=generation||found->second->decoder.get()!=decoder)return;auto& stream=*found->second;auto buffer=stream.decoder->read();if(!buffer.isValid())return;auto format=buffer.format();stream.rate=unsigned(format.sampleRate());const auto* data=buffer.constData<char>();const int channels=format.channelCount(),width=format.bytesPerSample();if(channels<1||width<1)return;
        for(qsizetype frame=0;frame<buffer.frameCount();++frame)for(int channel=0;channel<2;++channel){const char* at=data+(frame*channels+std::min(channel,channels-1))*width;double sample=0;switch(format.sampleFormat()){case QAudioFormat::Int16:{qint16 value;std::memcpy(&value,at,2);sample=value/32768.;break;}case QAudioFormat::Int32:{qint32 value;std::memcpy(&value,at,4);sample=value/2147483648.;break;}case QAudioFormat::Float:{float value;std::memcpy(&value,at,4);sample=value;break;}case QAudioFormat::UInt8:sample=(std::uint8_t(*at)-128)/128.;break;default:break;}if(stream.pcm.size()<30000000)stream.pcm.push_back(float(std::clamp(sample,-1.,1.)));}
    });
    connect(stream.decoder.get(),&QAudioDecoder::finished,this,[this,id,generation,decoder]{auto found=streams_.find(id);if(found==streams_.end()||found->second->generation!=generation||found->second->decoder.get()!=decoder||found->second->pcm.empty())return;auto& stream=*found->second;if(stream.pcm.size()>stream.deliveredSamples){auto fresh=std::make_shared<const std::vector<float>>(stream.pcm.begin()+stream.deliveredSamples,stream.pcm.end());stream.deliveredSamples=stream.pcm.size();if(decoded)decoded(id,std::move(fresh),stream.rate,generation);}});
    connect(stream.decoder.get(),qOverload<QAudioDecoder::Error>(&QAudioDecoder::error),this,[this,id,generation,decoder](QAudioDecoder::Error){auto found=streams_.find(id);if(found==streams_.end()||found->second->generation!=generation||found->second->decoder.get()!=decoder)return;if(notice)notice("VS1053 decoder: "+found->second->decoder->errorString());});stream.decoder->start();
}
